public final class BubbleSort {

    private BubbleSort() {
    }

    private static void bubbleSort(int[] values) {
        for (int pass = 0; pass < values.length - 1; pass++) {
            boolean swapped = false;

            for (int leftIndex = 0; leftIndex < values.length - pass - 1; leftIndex++) {
                if (isOutOfOrder(values, leftIndex)) {
                    swap(values, leftIndex, leftIndex + 1);
                    swapped = true;
                }
            }

            if (!swapped) {
                break;
            }
        }
    }

    private static boolean isOutOfOrder(int[] values, int leftIndex) {
        return values[leftIndex] > values[leftIndex + 1];
    }

    private static void swap(int[] values, int firstIndex, int secondIndex) {
        int temp = values[firstIndex];
        values[firstIndex] = values[secondIndex];
        values[secondIndex] = temp;
    }

    private static void printArray(int[] values) {
        for (int value : values) {
            System.out.print(value + " ");
        }
        System.out.println();
    }

    public static void main(String[] args) {
        int[] values = {64, 34, 25, 12, 22, 11, 90};

        bubbleSort(values);
        System.out.println("Sorted array: ");
        printArray(values);
    }
}
